  #define ETM_TRCVICTLR_EVENT_SEL_Disabled (0x00UL)  /*!< This event is not filtered.                                          */
  #define ETM_TRCVICTLR_EVENT_SEL_Enabled (0x01UL)   /*!< This event is filtered.                                              */

