/* MCAN_TSCV: Timestamp Counter Value */
  #define MCAN_TSCV_ResetValue (0x00000000UL)        /*!< Reset value of TSCV register.                                        */

/* TSC @Bits 0..15 : Timestamp Counter */
  #define MCAN_TSCV_TSC_Pos (0UL)                    /*!< Position of TSC field.                                               */
  #define MCAN_TSCV_TSC_Msk (0xFFFFUL << MCAN_TSCV_TSC_Pos) /*!< Bit mask of TSC field.                                        */


/* MCAN_TOCC: Timeout Counter Configuration */
  #define MCAN_TOCC_ResetValue (0x00000000UL)        /*!< Reset value of TOCC register.                                        */

/* ETOC @Bit 0 : Enable Timeout Counter */
  #define MCAN_TOCC_ETOC_Pos (0UL)                   /*!< Position of ETOC field.                                              */
  #define MCAN_TOCC_ETOC_Msk (0x1UL << MCAN_TOCC_ETOC_Pos) /*!< Bit mask of ETOC field.                                        */
  #define MCAN_TOCC_ETOC_Min (0x0UL)                 /*!< Min enumerator value of ETOC field.                                  */
  #define MCAN_TOCC_ETOC_Max (0x1UL)                 /*!< Max enumerator value of ETOC field.                                  */
  #define MCAN_TOCC_ETOC_Disabled (0x0UL)            /*!< Timeout Counter disabled                                             */
  #define MCAN_TOCC_ETOC_Enabled (0x1UL)             /*!< Timeout Counter enabled                                              */

/* TOS @Bits 1..2 : Timeout Select */
  #define MCAN_TOCC_TOS_Pos (1UL)                    /*!< Position of TOS field.                                               */
  #define MCAN_TOCC_TOS_Msk (0x3UL << MCAN_TOCC_TOS_Pos) /*!< Bit mask of TOS field.                                           */
  #define MCAN_TOCC_TOS_Min (0x0UL)                  /*!< Min enumerator value of TOS field.                                   */
  #define MCAN_TOCC_TOS_Max (0x3UL)                  /*!< Max enumerator value of TOS field.                                   */
  #define MCAN_TOCC_TOS_Continuous (0x0UL)           /*!< Continuous operation                                                 */
  #define MCAN_TOCC_TOS_TxEvent (0x1UL)              /*!< Timeout controlled by Tx Event FIFO                                  */
  #define MCAN_TOCC_TOS_RxFifo0 (0x2UL)              /*!< Timeout controlled by Rx FIFO 0                                      */
  #define MCAN_TOCC_TOS_RxFifo1 (0x3UL)              /*!< Timeout controlled by Rx FIFO 1                                      */

/* TOP @Bits 16..31 : Timeout Period */
  #define MCAN_TOCC_TOP_Pos (16UL)                   /*!< Position of TOP field.                                               */
  #define MCAN_TOCC_TOP_Msk (0xFFFFUL << MCAN_TOCC_TOP_Pos) /*!< Bit mask of TOP field.                                        */


/* MCAN_TOCV: Timeout Counter Value */
  #define MCAN_TOCV_ResetValue (0x00000000UL)        /*!< Reset value of TOCV register.                                        */

/* TOC @Bits 0..15 : Timeout Counter */
  #define MCAN_TOCV_TOC_Pos (0UL)                    /*!< Position of TOC field.                                               */
  #define MCAN_TOCV_TOC_Msk (0xFFFFUL << MCAN_TOCV_TOC_Pos) /*!< Bit mask of TOC field.                                        */


/* MCAN_ECR: Error Counter Register */
  #define MCAN_ECR_ResetValue (0x00000000UL)         /*!< Reset value of ECR register.                                         */

/* TEC @Bits 0..7 : Transmit Error Counter */
  #define MCAN_ECR_TEC_Pos (0UL)                     /*!< Position of TEC field.                                               */
  #define MCAN_ECR_TEC_Msk (0xFFUL << MCAN_ECR_TEC_Pos) /*!< Bit mask of TEC field.                                            */

/* REC @Bits 8..14 : Receive Error Counter */
  #define MCAN_ECR_REC_Pos (8UL)                     /*!< Position of REC field.                                               */
  #define MCAN_ECR_REC_Msk (0x7FUL << MCAN_ECR_REC_Pos) /*!< Bit mask of REC field.                                            */

/* RP @Bit 15 : Receive Error Passive */
  #define MCAN_ECR_RP_Pos (15UL)                     /*!< Position of RP field.                                                */
  #define MCAN_ECR_RP_Msk (0x1UL << MCAN_ECR_RP_Pos) /*!< Bit mask of RP field.                                                */
  #define MCAN_ECR_RP_Min (0x0UL)                    /*!< Min enumerator value of RP field.                                    */
  #define MCAN_ECR_RP_Max (0x1UL)                    /*!< Max enumerator value of RP field.                                    */
  #define MCAN_ECR_RP_Below (0x0UL)                  /*!< The Receive Error Counter is below the error passive level of 128    */
  #define MCAN_ECR_RP_Reached (0x1UL)                /*!< The Receive Error Counter has reached the error passive level of 128 */

/* CEL @Bits 16..23 : CAN Error Logging */
  #define MCAN_ECR_CEL_Pos (16UL)                    /*!< Position of CEL field.                                               */
  #define MCAN_ECR_CEL_Msk (0xFFUL << MCAN_ECR_CEL_Pos) /*!< Bit mask of CEL field.                                            */


/* MCAN_PSR: Protocol Status Register */
  #define MCAN_PSR_ResetValue (0x00000000UL)         /*!< Reset value of PSR register.                                         */

/* LEC @Bits 0..2 : Last Error Code */
  #define MCAN_PSR_LEC_Pos (0UL)                     /*!< Position of LEC field.                                               */
  #define MCAN_PSR_LEC_Msk (0x7UL << MCAN_PSR_LEC_Pos) /*!< Bit mask of LEC field.                                             */
  #define MCAN_PSR_LEC_Min (0x0UL)                   /*!< Min enumerator value of LEC field.                                   */
  #define MCAN_PSR_LEC_Max (0x7UL)                   /*!< Max enumerator value of LEC field.                                   */
  #define MCAN_PSR_LEC_NoError (0x0UL)               /*!< No error occurred since LEC has been reset by successful reception or
                                                          transmission.*/
  #define MCAN_PSR_LEC_StuffError (0x1UL)            /*!< More than 5 equal bits in a sequence have occurred in a part of a
                                                          received message where this is not allowed.*/
  #define MCAN_PSR_LEC_FormError (0x2UL)             /*!< A fixed format part of a received frame has the wrong format.        */
  #define MCAN_PSR_LEC_AckError (0x3UL)              /*!< The message transmitted by the MCAN was not acknowledged by another
                                                          node.*/
  #define MCAN_PSR_LEC_Bit1Error (0x4UL)             /*!< During the transmission of a message (with the exception of the
                                                          arbitration field), the device wanted to send a recessive level (bit
                                                          of logical value 1), but the monitored bus value was dominant.*/
  #define MCAN_PSR_LEC_Bit0Error (0x5UL)             /*!< During the transmission of a message (or acknowledge bit, or active
                                                          error flag, or overload flag), the device wanted to send a dominant
                                                          level (data or identifier bit logical value '0'), but the monitored
                                                          bus value was recessive. During Bus_Off recovery this status is set
                                                          each time a sequence of 11 recessive bits has been monitored. This
                                                          enables the CPU to monitor the proceeding of the Bus_Off recovery
                                                          sequence (indicating the bus is not stuck at dominant or continuously
                                                          disturbed).*/
  #define MCAN_PSR_LEC_CRCError (0x6UL)              /*!< The CRC check sum of a received message was incorrect. The CRC of an
                                                          incoming message does not match with the CRC calculated from the
                                                          received data.*/
  #define MCAN_PSR_LEC_NoChange (0x7UL)              /*!< Any read access to the Protocol Status Register re-initializes the LEC
                                                          to '7'. When the LEC shows the value '7', no CAN bus event was
                                                          detected since the last CPU read access to the Protocol Status
                                                          Register.*/

/* ACT @Bits 3..4 : Activity */
  #define MCAN_PSR_ACT_Pos (3UL)                     /*!< Position of ACT field.                                               */
  #define MCAN_PSR_ACT_Msk (0x3UL << MCAN_PSR_ACT_Pos) /*!< Bit mask of ACT field.                                             */
  #define MCAN_PSR_ACT_Min (0x0UL)                   /*!< Min enumerator value of ACT field.                                   */
  #define MCAN_PSR_ACT_Max (0x3UL)                   /*!< Max enumerator value of ACT field.                                   */
  #define MCAN_PSR_ACT_Synchronizing (0x0UL)         /*!< Node is synchronizing on CAN communication                           */
  #define MCAN_PSR_ACT_Idle (0x1UL)                  /*!< Node is neither receiver nor tr ansmitter                            */
  #define MCAN_PSR_ACT_Receiver (0x2UL)              /*!< Node is operating as receiver                                        */
  #define MCAN_PSR_ACT_Transmitter (0x3UL)           /*!< Node is operating as transmitter                                     */

/* EP @Bit 5 : Error Passive */
  #define MCAN_PSR_EP_Pos (5UL)                      /*!< Position of EP field.                                                */
  #define MCAN_PSR_EP_Msk (0x1UL << MCAN_PSR_EP_Pos) /*!< Bit mask of EP field.                                                */
  #define MCAN_PSR_EP_Min (0x0UL)                    /*!< Min enumerator value of EP field.                                    */
  #define MCAN_PSR_EP_Max (0x1UL)                    /*!< Max enumerator value of EP field.                                    */
  #define MCAN_PSR_EP_Active (0x0UL)                 /*!< The MCAN is in the Error_Active state. It normally takes part in bus
                                                          communication and sends an active error flag when an error has been
                                                          detected*/
  #define MCAN_PSR_EP_Passive (0x1UL)                /*!< The MCAN is in the Error_Passive state                               */

/* EW @Bit 6 : Warning Status */
  #define MCAN_PSR_EW_Pos (6UL)                      /*!< Position of EW field.                                                */
  #define MCAN_PSR_EW_Msk (0x1UL << MCAN_PSR_EW_Pos) /*!< Bit mask of EW field.                                                */
  #define MCAN_PSR_EW_Min (0x0UL)                    /*!< Min enumerator value of EW field.                                    */
  #define MCAN_PSR_EW_Max (0x1UL)                    /*!< Max enumerator value of EW field.                                    */
  #define MCAN_PSR_EW_Below (0x0UL)                  /*!< Both error counters are below the Error_Warning limit of 96          */
  #define MCAN_PSR_EW_Reached (0x1UL)                /*!< At least one of error counter has reached the Error_Warning limit of
                                                          96*/

/* BO @Bit 7 : Bus_Off Status */
  #define MCAN_PSR_BO_Pos (7UL)                      /*!< Position of BO field.                                                */
  #define MCAN_PSR_BO_Msk (0x1UL << MCAN_PSR_BO_Pos) /*!< Bit mask of BO field.                                                */
  #define MCAN_PSR_BO_Min (0x0UL)                    /*!< Min enumerator value of BO field.                                    */
  #define MCAN_PSR_BO_Max (0x1UL)                    /*!< Max enumerator value of BO field.                                    */
  #define MCAN_PSR_BO_On (0x0UL)                     /*!< The MCAN is not Bus_Off                                              */
  #define MCAN_PSR_BO_Off (0x1UL)                    /*!< The MCAN is in Bus_Off state                                         */

/* DLEC @Bits 8..10 : Data Phase Last Error Code */
  #define MCAN_PSR_DLEC_Pos (8UL)                    /*!< Position of DLEC field.                                              */
  #define MCAN_PSR_DLEC_Msk (0x7UL << MCAN_PSR_DLEC_Pos) /*!< Bit mask of DLEC field.                                          */

/* RESI @Bit 11 : ESI flag of last received CAN FD Message */
  #define MCAN_PSR_RESI_Pos (11UL)                   /*!< Position of RESI field.                                              */
  #define MCAN_PSR_RESI_Msk (0x1UL << MCAN_PSR_RESI_Pos) /*!< Bit mask of RESI field.                                          */
  #define MCAN_PSR_RESI_Min (0x0UL)                  /*!< Min enumerator value of RESI field.                                  */
  #define MCAN_PSR_RESI_Max (0x1UL)                  /*!< Max enumerator value of RESI field.                                  */
  #define MCAN_PSR_RESI_NotReceived (0x0UL)          /*!< Last received CAN FD message did not ha ve its ESI flag set          */
  #define MCAN_PSR_RESI_Received (0x1UL)             /*!< Last received CAN FD message had its ESI flag set                    */

/* RBRS @Bit 12 : BRS flag of last received CAN FD Message */
  #define MCAN_PSR_RBRS_Pos (12UL)                   /*!< Position of RBRS field.                                              */
  #define MCAN_PSR_RBRS_Msk (0x1UL << MCAN_PSR_RBRS_Pos) /*!< Bit mask of RBRS field.                                          */
  #define MCAN_PSR_RBRS_Min (0x0UL)                  /*!< Min enumerator value of RBRS field.                                  */
  #define MCAN_PSR_RBRS_Max (0x1UL)                  /*!< Max enumerator value of RBRS field.                                  */
  #define MCAN_PSR_RBRS_NotReceived (0x0UL)          /*!< Last received CAN FD message did not ha ve its BRS flag set          */
  #define MCAN_PSR_RBRS_Received (0x1UL)             /*!< Last received CAN FD message had its BRS flag set                    */

/* RFDF @Bit 13 : Received a CAN FD Message */
  #define MCAN_PSR_RFDF_Pos (13UL)                   /*!< Position of RFDF field.                                              */
  #define MCAN_PSR_RFDF_Msk (0x1UL << MCAN_PSR_RFDF_Pos) /*!< Bit mask of RFDF field.                                          */
  #define MCAN_PSR_RFDF_Min (0x0UL)                  /*!< Min enumerator value of RFDF field.                                  */
  #define MCAN_PSR_RFDF_Max (0x1UL)                  /*!< Max enumerator value of RFDF field.                                  */
  #define MCAN_PSR_RFDF_NotReceived (0x0UL)          /*!< Since this bit was reset by the CPU, no CAN FD message has been
                                                          received*/
  #define MCAN_PSR_RFDF_Received (0x1UL)             /*!< Message in CAN FD format with FDF flag set has been received         */

/* PXE @Bit 14 : Protocol Exception Event */
  #define MCAN_PSR_PXE_Pos (14UL)                    /*!< Position of PXE field.                                               */
  #define MCAN_PSR_PXE_Msk (0x1UL << MCAN_PSR_PXE_Pos) /*!< Bit mask of PXE field.                                             */
  #define MCAN_PSR_PXE_Min (0x0UL)                   /*!< Min enumerator value of PXE field.                                   */
  #define MCAN_PSR_PXE_Max (0x1UL)                   /*!< Max enumerator value of PXE field.                                   */
  #define MCAN_PSR_PXE_NotTriggered (0x0UL)          /*!< No protocol exception event occurred since last read access          */
  #define MCAN_PSR_PXE_Triggered (0x1UL)             /*!< Protocol exception event occurred                                    */

/* TDCV @Bits 16..22 : Transmitter Delay Compensation Value */
  #define MCAN_PSR_TDCV_Pos (16UL)                   /*!< Position of TDCV field.                                              */
  #define MCAN_PSR_TDCV_Msk (0x7FUL << MCAN_PSR_TDCV_Pos) /*!< Bit mask of TDCV field.                                         */


/* MCAN_TDCR: Transmitter Delay Compensation Register */
  #define MCAN_TDCR_ResetValue (0x00000000UL)        /*!< Reset value of TDCR register.                                        */

/* TDCF @Bits 0..6 : Transmitter Delay Compensation Filter Window Length */
  #define MCAN_TDCR_TDCF_Pos (0UL)                   /*!< Position of TDCF field.                                              */
  #define MCAN_TDCR_TDCF_Msk (0x7FUL << MCAN_TDCR_TDCF_Pos) /*!< Bit mask of TDCF field.                                       */

/* TDCO @Bits 8..14 : Transmitter Delay Compensation SSP Offset */
  #define MCAN_TDCR_TDCO_Pos (8UL)                   /*!< Position of TDCO field.                                              */
  #define MCAN_TDCR_TDCO_Msk (0x7FUL << MCAN_TDCR_TDCO_Pos) /*!< Bit mask of TDCO field.                                       */


/* MCAN_IR: Interrupt Register */
  #define MCAN_IR_ResetValue (0x00000000UL)          /*!< Reset value of IR register.                                          */

/* RF0N @Bit 0 : Rx FIFO 0 New Message */
  #define MCAN_IR_RF0N_Pos (0UL)                     /*!< Position of RF0N field.                                              */
  #define MCAN_IR_RF0N_Msk (0x1UL << MCAN_IR_RF0N_Pos) /*!< Bit mask of RF0N field.                                            */
  #define MCAN_IR_RF0N_Min (0x0UL)                   /*!< Min enumerator value of RF0N field.                                  */
  #define MCAN_IR_RF0N_Max (0x1UL)                   /*!< Max enumerator value of RF0N field.                                  */
  #define MCAN_IR_RF0N_Clear (0x1UL)                 /*!< Write '1' to clear interrupt flag                                    */
  #define MCAN_IR_RF0N_NotGenerated (0x0UL)          /*!< No new message written to Rx FIFO 0                                  */
  #define MCAN_IR_RF0N_Generated (0x1UL)             /*!< New message written to Rx FIFO 0                                     */

/* RF0W @Bit 1 : Rx FIFO 0 Watermark Reached */
  #define MCAN_IR_RF0W_Pos (1UL)                     /*!< Position of RF0W field.                                              */
  #define MCAN_IR_RF0W_Msk (0x1UL << MCAN_IR_RF0W_Pos) /*!< Bit mask of RF0W field.                                            */
  #define MCAN_IR_RF0W_Min (0x0UL)                   /*!< Min enumerator value of RF0W field.                                  */
  #define MCAN_IR_RF0W_Max (0x1UL)                   /*!< Max enumerator value of RF0W field.                                  */
  #define MCAN_IR_RF0W_Clear (0x1UL)                 /*!< Write '1' to clear interrupt flag                                    */
  #define MCAN_IR_RF0W_NotGenerated (0x0UL)          /*!< Rx FIFO 0 fill level below watermark                                 */
  #define MCAN_IR_RF0W_Generated (0x1UL)             /*!< Rx FIFO 0 fill level reached watermark                               */

/* RF0F @Bit 2 : Rx FIFO 0 Full */
  #define MCAN_IR_RF0F_Pos (2UL)                     /*!< Position of RF0F field.                                              */
  #define MCAN_IR_RF0F_Msk (0x1UL << MCAN_IR_RF0F_Pos) /*!< Bit mask of RF0F field.                                            */
  #define MCAN_IR_RF0F_Min (0x0UL)                   /*!< Min enumerator value of RF0F field.                                  */
  #define MCAN_IR_RF0F_Max (0x1UL)                   /*!< Max enumerator value of RF0F field.                                  */
  #define MCAN_IR_RF0F_Clear (0x1UL)                 /*!< Write '1' to clear interrupt flag                                    */
  #define MCAN_IR_RF0F_NotGenerated (0x0UL)          /*!< Rx FIFO 0 not full                                                   */
  #define MCAN_IR_RF0F_Generated (0x1UL)             /*!< Rx FIFO 0 full                                                       */

/* RF0L @Bit 3 : Rx FIFO 0 Message Lost */
  #define MCAN_IR_RF0L_Pos (3UL)                     /*!< Position of RF0L field.                                              */
  #define MCAN_IR_RF0L_Msk (0x1UL << MCAN_IR_RF0L_Pos) /*!< Bit mask of RF0L field.                                            */
  #define MCAN_IR_RF0L_Min (0x0UL)                   /*!< Min enumerator value of RF0L field.                                  */
  #define MCAN_IR_RF0L_Max (0x1UL)                   /*!< Max enumerator value of RF0L field.                                  */
  #define MCAN_IR_RF0L_Clear (0x1UL)                 /*!< Write '1' to clear interrupt flag                                    */
  #define MCAN_IR_RF0L_NotGenerated (0x0UL)          /*!< No Rx FIFO 0 message lost                                            */
  #define MCAN_IR_RF0L_Generated (0x1UL)             /*!< Rx FIFO 0 message lost, also set after write attempt to Rx FIFO 0 of
                                                          size zero*/

/* RF1N @Bit 4 : Rx FIFO 1 New Message */
  #define MCAN_IR_RF1N_Pos (4UL)                     /*!< Position of RF1N field.                                              */
  #define MCAN_IR_RF1N_Msk (0x1UL << MCAN_IR_RF1N_Pos) /*!< Bit mask of RF1N field.                                            */
  #define MCAN_IR_RF1N_Min (0x0UL)                   /*!< Min enumerator value of RF1N field.                                  */
  #define MCAN_IR_RF1N_Max (0x1UL)                   /*!< Max enumerator value of RF1N field.                                  */
  #define MCAN_IR_RF1N_Clear (0x1UL)                 /*!< Write '1' to clear interrupt flag                                    */
  #define MCAN_IR_RF1N_NotGenerated (0x0UL)          /*!< No new message written to Rx FIFO 1                                  */
  #define MCAN_IR_RF1N_Generated (0x1UL)             /*!< New message written to Rx FIFO 1                                     */

/* RF1W @Bit 5 : Rx FIFO 1 Watermark Reached */
  #define MCAN_IR_RF1W_Pos (5UL)                     /*!< Position of RF1W field.                                              */
  #define MCAN_IR_RF1W_Msk (0x1UL << MCAN_IR_RF1W_Pos) /*!< Bit mask of RF1W field.                                            */
  #define MCAN_IR_RF1W_Min (0x0UL)                   /*!< Min enumerator value of RF1W field.                                  */
  #define MCAN_IR_RF1W_Max (0x1UL)                   /*!< Max enumerator value of RF1W field.                                  */
  #define MCAN_IR_RF1W_Clear (0x1UL)                 /*!< Write '1' to clear interrupt flag                                    */
  #define MCAN_IR_RF1W_NotGenerated (0x0UL)          /*!< Rx FIFO 1 fill level below watermark                                 */
  #define MCAN_IR_RF1W_Generated (0x1UL)             /*!< Rx FIFO 1 fill level reached watermark                               */

/* RF1F @Bit 6 : Rx FIFO 1 Full */
  #define MCAN_IR_RF1F_Pos (6UL)                     /*!< Position of RF1F field.                                              */
  #define MCAN_IR_RF1F_Msk (0x1UL << MCAN_IR_RF1F_Pos) /*!< Bit mask of RF1F field.                                            */
  #define MCAN_IR_RF1F_Min (0x0UL)                   /*!< Min enumerator value of RF1F field.                                  */
  #define MCAN_IR_RF1F_Max (0x1UL)                   /*!< Max enumerator value of RF1F field.                                  */
  #define MCAN_IR_RF1F_Clear (0x1UL)                 /*!< Write '1' to clear interrupt flag                                    */
  #define MCAN_IR_RF1F_NotGenerated (0x0UL)          /*!< Rx FIFO 1 not full                                                   */
  #define MCAN_IR_RF1F_Generated (0x1UL)             /*!< Rx FIFO 1 full                                                       */

/* RF1L @Bit 7 : Rx FIFO 1 Message Lost */
  #define MCAN_IR_RF1L_Pos (7UL)                     /*!< Position of RF1L field.                                              */
  #define MCAN_IR_RF1L_Msk (0x1UL << MCAN_IR_RF1L_Pos) /*!< Bit mask of RF1L field.                                            */
  #define MCAN_IR_RF1L_Min (0x0UL)                   /*!< Min enumerator value of RF1L field.                                  */
  #define MCAN_IR_RF1L_Max (0x1UL)                   /*!< Max enumerator value of RF1L field.                                  */
  #define MCAN_IR_RF1L_Clear (0x1UL)                 /*!< Write '1' to clear interrupt flag                                    */
  #define MCAN_IR_RF1L_NotGenerated (0x0UL)          /*!< No Rx FIFO 1 message lost                                            */
  #define MCAN_IR_RF1L_Generated (0x1UL)             /*!< Rx FIFO 1 message lost, also set after write attempt to Rx FIFO 1 of
                                                          size zero*/

/* HPM @Bit 8 : High Priority Message */
  #define MCAN_IR_HPM_Pos (8UL)                      /*!< Position of HPM field.                                               */
  #define MCAN_IR_HPM_Msk (0x1UL << MCAN_IR_HPM_Pos) /*!< Bit mask of HPM field.                                               */
  #define MCAN_IR_HPM_Min (0x0UL)                    /*!< Min enumerator value of HPM field.                                   */
  #define MCAN_IR_HPM_Max (0x1UL)                    /*!< Max enumerator value of HPM field.                                   */
  #define MCAN_IR_HPM_Clear (0x1UL)                  /*!< Write '1' to clear interrupt flag                                    */
  #define MCAN_IR_HPM_NotGenerated (0x0UL)           /*!< No high priority message received                                    */
  #define MCAN_IR_HPM_Generated (0x1UL)              /*!< High priority message received                                       */

/* TC @Bit 9 : Transmission Completed */
  #define MCAN_IR_TC_Pos (9UL)                       /*!< Position of TC field.                                                */
  #define MCAN_IR_TC_Msk (0x1UL << MCAN_IR_TC_Pos)   /*!< Bit mask of TC field.                                                */
  #define MCAN_IR_TC_Min (0x0UL)                     /*!< Min enumerator value of TC field.                                    */
  #define MCAN_IR_TC_Max (0x1UL)                     /*!< Max enumerator value of TC field.                                    */
  #define MCAN_IR_TC_Clear (0x1UL)                   /*!< Write '1' to clear interrupt flag                                    */
  #define MCAN_IR_TC_NotGenerated (0x0UL)            /*!< No transmission completed                                            */
  #define MCAN_IR_TC_Generated (0x1UL)               /*!< Transmission completed                                               */

/* TCF @Bit 10 : Transmission Cancellation Finished */
  #define MCAN_IR_TCF_Pos (10UL)                     /*!< Position of TCF field.                                               */
  #define MCAN_IR_TCF_Msk (0x1UL << MCAN_IR_TCF_Pos) /*!< Bit mask of TCF field.                                               */
  #define MCAN_IR_TCF_Min (0x0UL)                    /*!< Min enumerator value of TCF field.                                   */
  #define MCAN_IR_TCF_Max (0x1UL)                    /*!< Max enumerator value of TCF field.                                   */
  #define MCAN_IR_TCF_Clear (0x1UL)                  /*!< Write '1' to clear interrupt flag                                    */
  #define MCAN_IR_TCF_NotGenerated (0x0UL)           /*!< No transmission cancellation finished                                */
