/* TFE @Bit 11 : Tx FIFO Empty */
  #define MCAN_IR_TFE_Pos (11UL)                     /*!< Position of TFE field.                                               */
  #define MCAN_IR_TFE_Msk (0x1UL << MCAN_IR_TFE_Pos) /*!< Bit mask of TFE field.                                               */
  #define MCAN_IR_TFE_Min (0x0UL)                    /*!< Min enumerator value of TFE field.                                   */
  #define MCAN_IR_TFE_Max (0x1UL)                    /*!< Max enumerator value of TFE field.                                   */
  #define MCAN_IR_TFE_Clear (0x1UL)                  /*!< Write '1' to clear interrupt flag                                    */
  #define MCAN_IR_TFE_NotGenerated (0x0UL)           /*!< Tx FIFO non-empty                                                    */
  #define MCAN_IR_TFE_Generated (0x1UL)              /*!< Tx FIFO empty                                                        */

/* TEFN @Bit 12 : Tx Event FIFO New Entry */
  #define MCAN_IR_TEFN_Pos (12UL)                    /*!< Position of TEFN field.                                              */
  #define MCAN_IR_TEFN_Msk (0x1UL << MCAN_IR_TEFN_Pos) /*!< Bit mask of TEFN field.                                            */
  #define MCAN_IR_TEFN_Min (0x0UL)                   /*!< Min enumerator value of TEFN field.                                  */
  #define MCAN_IR_TEFN_Max (0x1UL)                   /*!< Max enumerator value of TEFN field.                                  */
