/* MVDMA_EVENTS_END: Event indicating that Sink data descriptor list has been completed. */
  #define MVDMA_EVENTS_END_ResetValue (0x00000000UL) /*!< Reset value of EVENTS_END register.                                  */

/* EVENTS_END @Bit 0 : Event indicating that Sink data descriptor list has been completed. */
  #define MVDMA_EVENTS_END_EVENTS_END_Pos (0UL)      /*!< Position of EVENTS_END field.                                        */
  #define MVDMA_EVENTS_END_EVENTS_END_Msk (0x1UL << MVDMA_EVENTS_END_EVENTS_END_Pos) /*!< Bit mask of EVENTS_END field.        */
  #define MVDMA_EVENTS_END_EVENTS_END_Min (0x0UL)    /*!< Min enumerator value of EVENTS_END field.                            */
  #define MVDMA_EVENTS_END_EVENTS_END_Max (0x1UL)    /*!< Max enumerator value of EVENTS_END field.                            */
  #define MVDMA_EVENTS_END_EVENTS_END_NotGenerated (0x0UL) /*!< Event not generated                                            */
