/* USBHSCORE_GOTGCTL: Control and Status Register */
  #define USBHSCORE_GOTGCTL_ResetValue (0x000D0000UL) /*!< Reset value of GOTGCTL register.                                    */

/* VBVALIDOVEN @Bit 2 : Mode: Host only. VBUS Valid Override Enable (VbvalidOvEn) */
  #define USBHSCORE_GOTGCTL_VBVALIDOVEN_Pos (2UL)    /*!< Position of VBVALIDOVEN field.                                       */
  #define USBHSCORE_GOTGCTL_VBVALIDOVEN_Msk (0x1UL << USBHSCORE_GOTGCTL_VBVALIDOVEN_Pos) /*!< Bit mask of VBVALIDOVEN field.   */
  #define USBHSCORE_GOTGCTL_VBVALIDOVEN_Min (0x0UL)  /*!< Min enumerator value of VBVALIDOVEN field.                           */
  #define USBHSCORE_GOTGCTL_VBVALIDOVEN_Max (0x1UL)  /*!< Max enumerator value of VBVALIDOVEN field.                           */
  #define USBHSCORE_GOTGCTL_VBVALIDOVEN_DISABLED (0x0UL) /*!< Override is disabled and bvalid signal from the respective PHY
                                                              selected is used internally by the controller*/
  #define USBHSCORE_GOTGCTL_VBVALIDOVEN_ENABLED (0x1UL) /*!< The vbus-valid signal received from the PHY is overridden with
                                                             GOTGCTL.VbvalidOvVal*/

/* VBVALIDOVVAL @Bit 3 : Mode: Host only. VBUS Valid OverrideValue (VbvalidOvVal) */
  #define USBHSCORE_GOTGCTL_VBVALIDOVVAL_Pos (3UL)   /*!< Position of VBVALIDOVVAL field.                                      */
